from core.prompts.domain_function_library import FractionOps, PolynomialOps, RadicalOps
from core.skill_policies.radical_logic import RadicalLogicEngine

def generate(level=1, **kwargs):
    dividend_coefficients = [-7, 4, -1]
    divisor_coefficients = [1, 2]

    quotient_coefficients, remainder_coefficients = PolynomialOps.div_qr(dividend_coefficients, divisor_coefficients)

    question_text = f"Divide the polynomial with coefficients {dividend_coefficients} by the linear divisor with coefficients {divisor_coefficients}. Report the quotient and the remainder."

    correct_answer = {
        "quotient_coefficients": quotient_coefficients,
        "remainder_coefficients": remainder_coefficients
    }

    oracle_payload = {"dividend_coefficients": dividend_coefficients, "divisor_coefficients": divisor_coefficients}

    return {
        "question_text": question_text,
        "correct_answer": correct_answer,
        "oracle_payload": oracle_payload
    }

